procedure:platform.apply_payment_status(.source_code:
declare
    v_old_status text;
    v_tenant_id uuid;
begin
    select pi.status, pi.tenant_id
    into v_old_status, v_tenant_id
    from platform.payment_intents pi
    where pi.id = p_intent_id
    for update;

    if not found then
        raise exception 'payment_intent % not found', p_intent_id;
    end if;

    if p_external_event_id is not null and exists (
        select 1
        from platform.payment_events pe
        where pe.payment_intent_id = p_intent_id
          and pe.external_event_id = p_external_event_id
    ) then
        return;
    end if;

    begin
        insert into platform.payment_events (
            payment_intent_id,
            tenant_id,
            event_type,
            old_status,
            new_status,
            source,
            external_event_id,
            payload
        )
        values (
            p_intent_id,
            v_tenant_id,
            p_event_type,
            v_old_status,
            p_new_status,
            p_source,
            p_external_event_id,
            coalesce(p_payload, '{}'::jsonb)
        );
    exception
        when unique_violation then
            return;
    end;

    update platform.payment_intents
    set status = p_new_status
    where id = p_intent_id;
end;

procedure:platform.bind_operation_contex.source_code:
begin
