procedure:platform.create_vault_secret(t.source_code:
begin
    if p_secret is null or p_name is null then
        raise exception 'secret and name are required';
    end if;

    if not exists (select 1 from pg_extension where extname = 'vault') then
        raise exception 'vault extension not available';
    end if;

    perform vault.create_secret(p_secret, p_name, coalesce(p_description, p_name));
end;

procedure:platform.create_vault_secret(t.definition:
CREATE OR REPLACE FUNCTION platform.create_vault_secret(p_secret text, p_name text, p_description text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    if p_secret is null or p_name is null then
        raise exception 'secret and name are required';
    end if;

    if not exists (select 1 from pg_extension where extname = 'vault') then
