    end if;

    v_method := upper(coalesce(p_method, 'POST'));

    if v_method = 'GET' then
        select net.http_get(
            url := p_url,
            headers := coalesce(p_headers, '{}'::jsonb),
            timeout_milliseconds := p_timeout_ms
        )
        into v_request_id;
    else
        select net.http_post(
            url := p_url,
            headers := coalesce(p_headers, '{}'::jsonb),
            body := coalesce(p_body, '{}'::jsonb),
            timeout_milliseconds := p_timeout_ms
        )
        into v_request_id;
    end if;

    return v_request_id;
end;

