procedure:platform.drop_old_log_partitio.source_code:
declare
    v_partition record;
    v_cutoff date;
begin
    v_cutoff := (date_trunc('month', now()) - p_retention)::date;

    for v_partition in
        select c.relname as partition_name
        from pg_inherits i
        join pg_class c on c.oid = i.inhrelid
        join pg_class p on p.oid = i.inhparent
        join pg_namespace n on n.oid = p.relnamespace
        where n.nspname = 'platform'
          and p.relname = p_base_table
          and c.relname ~ ('^' || p_base_table || '_\d{4}_\d{2}$')
    loop
        if to_date(right(v_partition.partition_name, 7), 'YYYY_MM') < v_cutoff then
            execute format(
                'drop table if exists platform.%I',
                v_partition.partition_name
            );
        end if;
    end loop;
end;

procedure:platform.enable_realtime(regcl.source_code:
declare
    v_schema text;
    v_table text;
    v_qualified text;
begin
    select n.nspname, c.relname
    into v_schema, v_table
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where c.oid = p_table;

    v_qualified := format('%I.%I', v_schema, v_table);

    if not exists (
        select 1
        from pg_publication_tables pt
        join pg_publication p on p.pubname = pt.pubname
        where p.pubname = 'supabase_realtime'
          and pt.schemaname = v_schema
          and pt.tablename = v_table
    ) then
        execute format(
            'alter publication supabase_realtime add table %s',
            v_qualified
        );
    end if;
end;

