procedure:platform.sync_http_request(tex.source_code:
declare
    v_request_id bigint;
    v_method text;
    v_result net.http_response_result;
    v_status_code int;
    v_response_body text;
begin
    if p_url is null or btrim(p_url) = '' then
        raise exception 'url is required';
    end if;

    if not exists (select 1 from pg_extension where extname = 'pg_net') then
        raise exception 'pg_net extension not available';
    end if;

    v_method := upper(coalesce(p_method, 'POST'));

    if v_method = 'GET' then
        select net.http_get(
            url := p_url,
            headers := case
                when p_content_type is not null and btrim(p_content_type) <> ''
                    then jsonb_build_object('Content-Type', p_content_type)
                else '{}'::jsonb
            end,
            timeout_milliseconds := p_timeout_ms
        )
        into v_request_id;
    elsif v_method = 'POST' then
        if coalesce(lower(p_content_type), 'application/json') = 'application/json' then
            select net.http_post(
                url := p_url,
                body := coalesce(p_body, '{}')::jsonb,
                headers := jsonb_build_object('Content-Type', 'application/json'),
                timeout_milliseconds := p_timeout_ms
            )
            into v_request_id;
        else
            insert into net.http_request_queue (method, url, headers, body, timeout_milliseconds)
            values (
                'POST',
                p_url,
                jsonb_build_object(
                    'Content-Type',
                    coalesce(nullif(btrim(p_content_type), ''), 'application/octet-stream')
                ),
                convert_to(coalesce(p_body, ''), 'UTF8'),
                p_timeout_ms
            )
            returning id into v_request_id;

            perform net.wake();
        end if;
    else
        raise exception 'unsupported HTTP method: %', p_method;
    end if;

    select net.http_collect_response(v_request_id, async := false)
    into v_result;

    if v_result.status <> 'SUCCESS'::net.request_status then
        raise exception 'HTTP request failed: %', coalesce(v_result.message, 'unknown error');
    end if;

    v_status_code := (v_result.response).status_code;
    v_response_body := (v_result.response).body;

    return jsonb_build_object(
        'status_code', v_status_code,
        'body', v_response_body
    );
end;

procedure:platform.sync_http_request(tex.definition:
CREATE OR REPLACE FUNCTION platform.sync_http_request(p_method text, p_url text, p_content_type text, p_body text, p_timeout_ms integer DEFAULT 15000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_request_id bigint;
    v_method text;
    v_result net.http_response_result;
    v_status_code int;
    v_response_body text;
begin
    if p_url is null or btrim(p_url) = '' then
        raise exception 'url is required';
    end if;

    if not exists (select 1 from pg_extension where extname = 'pg_net') then
        raise exception 'pg_net extension not available';
    end if;

    v_method := upper(coalesce(p_method, 'POST'));

    if v_method = 'GET' then
        select net.http_get(
            url := p_url,
            headers := case
                when p_content_type is not null and btrim(p_content_type) <> ''
                    then jsonb_build_object('Content-Type', p_content_type)
                else '{}'::jsonb
            end,
            timeout_milliseconds := p_timeout_ms
        )
        into v_request_id;
    elsif v_method = 'POST' then
        if coalesce(lower(p_content_type), 'application/json') = 'application/json' then
            select net.http_post(
                url := p_url,
                body := coalesce(p_body, '{}')::jsonb,
                headers := jsonb_build_object('Content-Type', 'application/json'),
                timeout_milliseconds := p_timeout_ms
            )
            into v_request_id;
        else
            insert into net.http_request_queue (method, url, headers, body, timeout_milliseconds)
            values (
                'POST',
                p_url,
                jsonb_build_object(
                    'Content-Type',
                    coalesce(nullif(btrim(p_content_type), ''), 'application/octet-stream')
                ),
                convert_to(coalesce(p_body, ''), 'UTF8'),
                p_timeout_ms
            )
            returning id into v_request_id;

            perform net.wake();
        end if;
    else
        raise exception 'unsupported HTTP method: %', p_method;
    end if;

    select net.http_collect_response(v_request_id, async := false)
    into v_result;

    if v_result.status <> 'SUCCESS'::net.request_status then
        raise exception 'HTTP request failed: %', coalesce(v_result.message, 'unknown error');
    end if;

    v_status_code := (v_result.response).status_code;
    v_response_body := (v_result.response).body;

    return jsonb_build_object(
        'status_code', v_status_code,
        'body', v_response_body
    );
end;
$function$

