procedure:public.auth_switch_tenant(json.source_code:
declare
    v_uid uuid;
    v_target_tid uuid;
    v_result jsonb;
begin
    p_payload := coalesce(p_payload, '{}'::jsonb);
    v_uid := auth.uid();
    if v_uid is null then
        raise exception 'authentication required';
    end if;
    if p_payload->>'tenant_id' is null then
        raise exception 'tenant_id is required';
    end if;

    v_target_tid := (p_payload->>'tenant_id')::uuid;
    v_result := public.auth_resolve_tenant_switch(v_uid, v_target_tid);

    update auth.users
    set raw_app_meta_data = coalesce(raw_app_meta_data, '{}'::jsonb)
        || jsonb_build_object('tenant_id', v_target_tid::text)
    where id = v_uid;

    return v_result;
end;

