procedure:public.enforce_tenant_owner_in.source_code:
declare
    v_owner_count int;
begin
    if tg_op = 'DELETE' then
        if old.role = 'owner' and old.is_active then
            select count(*)
            into v_owner_count
            from public.tenant_memberships tm
            where tm.tenant_id = old.tenant_id
              and tm.role = 'owner'
              and tm.is_active = true
              and tm.id <> old.id;

            if v_owner_count = 0 then
                raise exception 'cannot remove last active owner from tenant';
            end if;
        end if;

        return old;
    end if;

    if tg_op = 'UPDATE' then
        if old.role = 'owner'
           and old.is_active
           and (new.role <> 'owner' or not new.is_active) then
            select count(*)
            into v_owner_count
            from public.tenant_memberships tm
            where tm.tenant_id = old.tenant_id
              and tm.role = 'owner'
              and tm.is_active = true
              and tm.id <> old.id;

            if v_owner_count = 0 then
                raise exception 'cannot demote or deactivate last active owner';
            end if;
        end if;
    end if;

    return new;
end;

