procedure:public.logistics_api(text,json.source_code:
begin
    p_payload := coalesce(p_payload, '{}'::jsonb);

    case p_op
        when 'list_logistics_templates', 'get_logistics_template', 'list_package_definitions', 'list_carriers',
             'get_carrier', 'list_warehouses', 'get_warehouse', 'list_label_templates', 'list_shipping_rules',
             'list_fulfilment_orders', 'get_fulfilment_order' then
            perform public.edge_require_tenant();
        when 'create_logistics_template', 'update_logistics_template', 'delete_logistics_template',
             'create_package_definition', 'update_package_definition', 'delete_package_definition',
             'create_warehouse', 'update_warehouse', 'delete_warehouse',
             'create_shipping_rule', 'update_shipping_rule', 'delete_shipping_rule',
             'create_fulfilment_order', 'update_fulfilment_order', 'delete_fulfilment_order',
             'dispatch_fulfilment_order' then
            perform public.edge_require_manager();
        when 'create_carrier', 'update_carrier', 'delete_carrier',
             'create_label_template', 'update_label_template', 'delete_label_template' then
            if not platform.is_platform_admin() then
                raise exception 'platform admin role required';
            end if;
        else
            raise exception 'unknown logistics_api operation: %', p_op;
    end case;

    return public.logistics_domain(p_op, p_payload);
end;

procedure:public.logistics_dispatch_fulf.source_code:
declare
    v_tid uuid;
    v_order record;
    v_queue_id text;
    v_merged jsonb;
begin
    v_tid := platform.current_tenant_id();

    select fo.id, fo.status, fo.property_id, fo.carrier_id, fo.warehouse_id,
           fo.label_template_id, fo.package_definition_id, fo.device_bundle_id
    into v_order
    from public.fulfilment_orders fo
    where fo.id = p_fulfilment_order_id
      and fo.tenant_id = v_tid
      and fo.deleted_at is null;

    if not found then
        raise exception 'fulfilment order not found';
    end if;

    if v_order.status <> 'ready_to_ship' then
        raise exception 'fulfilment order must be ready_to_ship before dispatch (current: %)', v_order.status;
    end if;

    v_merged := coalesce(p_payload, '{}'::jsonb)
        || jsonb_build_object(
            'property_id', v_order.property_id,
            'carrier_id', v_order.carrier_id,
            'warehouse_id', v_order.warehouse_id,
            'label_template_id', v_order.label_template_id,
            'package_definition_id', v_order.package_definition_id,
            'device_bundle_id', v_order.device_bundle_id
        );

    v_queue_id := platform.enqueue_shipment_dispatch(
        v_tid,
        v_order.id,
        v_merged
    );

    return jsonb_build_object(
        'queued', true,
        'dispatch_queue_id', v_queue_id,
        'fulfilment_order_id', v_order.id
    );
end;

