procedure:public.logistics_domain(text,j.source_code:
declare
    v_tid uuid;
    v_row record;
    v_result jsonb;
    v_template record;
begin
    p_payload := coalesce(p_payload, '{}'::jsonb);

    case p_op
        when 'list_logistics_templates' then
            v_tid := platform.current_tenant_id();
            if v_tid is null then
                raise exception 'no active tenant';
            end if;

            select coalesce(
                jsonb_agg(to_jsonb(lt) order by lt.name),
                '[]'::jsonb
            )
            into v_result
            from (
                select
                    l.id,
                    l.tenant_id,
                    l.is_system,
                    l.name,
                    l.description,
                    l.is_active,
                    l.created_at,
                    l.updated_at
                from public.logistics_templates l
                where l.tenant_id = v_tid
                   or l.is_system = true
            ) lt;

            return v_result;

        when 'get_logistics_template' then
            v_tid := platform.current_tenant_id();
            if v_tid is null then
                raise exception 'no active tenant';
            end if;

            select
                l.id,
                l.tenant_id,
                l.is_system,
                l.name,
                l.description,
                l.is_active,
                l.created_at,
                l.updated_at
            into v_template
            from public.logistics_templates l
            where l.id = (p_payload->>'id')::uuid
              and (l.tenant_id = v_tid or l.is_system = true);

            if not found then
                raise exception 'Logistics template not found';
            end if;

