procedure:public.onboarding_lifecycle_ge.definition:
CREATE OR REPLACE FUNCTION public.onboarding_lifecycle_get(p_property_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_tid uuid;
    v_result jsonb;
begin
    v_tid := platform.current_tenant_id();
    if v_tid is null then
        raise exception 'no active tenant';
    end if;

    select to_jsonb(t) into v_result
    from (
        select
            ol.id,
            ol.tenant_id,
            ol.property_id,
            ol.session_id,
            ol.current_state,
            ol.created_at,
            ol.updated_at
        from public.onboarding_lifecycle ol
        where ol.property_id = p_property_id
          and ol.tenant_id = v_tid
    ) t;

    return coalesce(v_result, 'null'::jsonb);
end;
$function$

